mapper.select:
select distinct * from mp_auth_user where id in
(select user from mp_auth_tenant_user where org = #{orgId})

    AND id not in
    (select distinct user from mp_auth_user_role where "ROLE" in

        role in

            #{roleId}


            and user != #{selfUserId}


    )


    AND id not in

        #{excludeUserId}


order by -update_time, username

select distinct o.*, ou.user as userId from mp_auth_org o left join mp_auth_tenant_user ou on ou.org = o.id where ou."USER" != ''
AND ou."USER" in
#{userId}

select
distinct u.*,
from mp_auth_user u
left join mp_auth_tenant_user ou on u.id = ou.user
left join mp_auth_user_role ur on u.id = ur.user


        AND u.id in (select user from mp_auth_tenant_user where org in

            #{orgId}

        )


        AND u.id in

            #{userId}



        AND u.id not in
        (select distinct user from mp_auth_user_role

            role in

                #{roleId}


                and user != #{selfUserId}


        )


        AND u.id not in

            #{excludeUserId}



        AND u.is_enabled = #{userCondition.isEnabled}


        AND u.is_audited = #{userCondition.isAudited}


        AND u.expired_time > #{currentDateTime}


        AND u.expired_time <= #{currentDateTime}


        AND ( u.username like CONCAT('%', #{userCondition.username}, '%') or u.name like CONCAT('%', #{userCondition.username}, '%'))


group by u.id

    ORDER BY
    ${order}
